return new[]{"PastelLeaves","PastelLayered","PastelProps","PastelFlowers"}.Select(n=>{var s=UnityEditor.AssetDatabase.LoadAssetAtPath<UnityEngine.Shader>("Assets/Materials/GardenPastel/"+n+".shadergraph");return new{name=n,shader=s==null?null:s.name,supported=s!=null&&s.isSupported,messages=s==null?null:UnityEditor.ShaderUtil.GetShaderMessages(s).Select(m=>new{severity=m.severity.ToString(),message=m.message}).ToArray()};}).ToArray();
